const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const taklamakanDesert = ee.Geometry.Point([83.6, 39.5]);
  const aoi = taklamakanDesert.buffer(100000); // 100km buffer to get a regional average

  const dateRange2019 = ee.DateRange('2019-02-01', '2019-02-28');
  const dateRange2020 = ee.DateRange('2020-02-01', '2020-02-29');

  // 2. Data Acquisition & Processing Function
  const collectionId = 'MODIS/061/MCD19A2_GRANULES';
  const aodBand = 'Optical_Depth_047';
  const qaBand = 'AOD_QA';

  const processYear = function(dateRange) {
    const collection = ee.ImageCollection(collectionId)
      .filterBounds(aoi)
      .filterDate(dateRange)
      .select([aodBand, qaBand]);

    const maskAndScale = function(image) {
      const qa = image.select(qaBand);
      // Best quality aerosol retrievals (bits 0-1 are 00)
      const qualityMask = qa.bitwiseAnd(3).eq(0);
      const aod = image.select(aodBand).multiply(0.001); // Apply scale factor
      return aod.updateMask(qualityMask);
    };

    const maskedCollection = collection.map(maskAndScale);
    return {
        collection: maskedCollection,
        imageCount: collection.size()
    };
  };

  // 3. Get Data for Each Year
  const data2019 = processYear(dateRange2019);
  const data2020 = processYear(dateRange2020);

  const imageCount2019 = data2019.imageCount.getInfo();
  const imageCount2020 = data2020.imageCount.getInfo();

  if (imageCount2019 === 0 || imageCount2020 === 0) {
    console.log(`Image Count 2019: ${imageCount2019}`);
    console.log(`Image Count 2020: ${imageCount2020}`);
    console.log("Empty collection for one or both years.");
    process.stdout.write("C1");
    return;
  }

  const aod2019 = data2019.collection.mean();
  const aod2020 = data2020.collection.mean();

  const scale = 3000;

  // 4. Calculation & Validation
  const stats2019 = aod2019.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const stats2020 = aod2020.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const mean2019 = stats2019[aodBand + '_mean'];
  const count2019 = stats2019[aodBand + '_count'];

  const mean2020 = stats2020[aodBand + '_mean'];
  const count2020 = stats2020[aodBand + '_count'];

  console.log(`Feb 2019 Initial Images: ${imageCount2019}`);
  console.log(`Feb 2020 Initial Images: ${imageCount2020}`);

  if (count2019 === 0 || count2020 === 0) {
    console.log(`Feb 2019 Valid Pixel Count: ${count2019}`);
    console.log(`Feb 2020 Valid Pixel Count: ${count2020}`);
    console.log("No valid pixels after quality masking.");
    process.stdout.write("C2");
    return;
  }

  if (mean2019 === null || mean2020 === null) {
      console.log(`Feb 2019 Mean AOD: ${mean2019}`);
      console.log(`Feb 2020 Mean AOD: ${mean2020}`);
      console.log("Calculation resulted in a null value.");
      process.stdout.write("C3");
      return;
  }

  // 5. Final Answer
  console.log(`Feb 2019 Mean AOD: ${mean2019.toFixed(4)} (Pixels: ${count2019})`);
  console.log(`Feb 2020 Mean AOD: ${mean2020.toFixed(4)} (Pixels: ${count2020})`);

  if (mean2020 > mean2019) {
    process.stdout.write("A");
  } else {
    process.stdout.write("B");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Error: ${e.toString()}`);
    process.stdout.write("D");
  }
}

initEE();
